const queries = [
  { q: "What was total revenue in fiscal 2025?", answer: "165.9", type: "factual" },
  { q: "How much cash and cash equivalents did the company hold at year end?", answer: "45.20", type: "factual" },
  { q: "What was net income in FY2024?", answer: "4.8", type: "factual" },
  { q: "What was research and development spending in FY2025?", answer: "42.00", type: "factual" },
  { q: "What was total stockholders' equity?", answer: "15.20", type: "factual" },
  { q: "What was the year-over-year growth rate of total sales?", answer: "25.0%", type: "paraphrase" },
  { q: "Why did Professional Services revenue decline?", answer: "low-margin", type: "contextual" },
  { q: "Will the drag from the services business continue into next year?", answer: "legacy customization", type: "contextual" },
  { q: "How long can the company operate using its current cash?", answer: "24 months", type: "paraphrase" },
  { q: "What happened to gross margin on services?", answer: "14.0%", type: "contextual" }
];
const strategies = ['fixed', 'semantic', 'section'];
const out = [];
queries.forEach((c, qi) => {
  strategies.forEach(s => out.push({ json: { qid: qi + 1, ...c, strategy: s } }));
});
return out;

const CONFIG = 'baseline (top-3)';
const rows = $input.all().map(i => i.json);

// Integrity checks
const wrong = rows.filter(r => r.chunk_strategy !== r.strategy);
if (wrong.length) throw new Error(`${wrong.length} chunks came from the wrong strategy - filter not applied`);
const byQuery = {};
rows.forEach(r => { (byQuery[r.qid + '|' + r.strategy] = byQuery[r.qid + '|' + r.strategy] || []).push(r); });
const badCounts = Object.entries(byQuery).filter(([k, v]) => v.length !== 3).map(([k]) => k);
if (badCounts.length) throw new Error('Not exactly 3 chunks for: ' + badCounts.join(', '));

// Per-query scoring
const perQuery = Object.values(byQuery).map(chunks => {
  const f = chunks[0];
  const ans = String(f.answer).toLowerCase();
  const rank = chunks.findIndex(c => c.chunk.toLowerCase().includes(ans));
  return {
    config: CONFIG, qid: f.qid, question: f.q, type: f.type, strategy: f.strategy,
    hit: rank >= 0 ? 1 : 0,
    rr: rank >= 0 ? +(1 / (rank + 1)).toFixed(3) : 0,
    hit_rank: rank >= 0 ? rank + 1 : null,
    hit_source: rank >= 0 ? chunks[rank].chunk_label : null,
    avg_chars: Math.round(chunks.reduce((a, c) => a + c.chunk.length, 0) / chunks.length),
    linked_by: f.linked_by
  };
});

// Summary per strategy and per strategy + query type
return perQuery.map(j => ({ json: j }));


return [...summary, ...perQuery].map(j => ({ json: j }));

const rows = $input.all().map(i => i.json);
const g = {};
const add = (k, cfg, r) => {
  const x = g[k] = g[k] || { config: cfg, n: 0, hit: 0, rr: 0, chars: 0 };
  x.n++; x.hit += r.hit; x.rr += r.rr; x.chars += r.avg_chars;
};
rows.forEach(r => {
  add(r.config + ' | ' + r.strategy, r.config, r);
  add(r.config + ' | ' + r.strategy + ' | ' + r.type, r.config, r);
});
return Object.entries(g).map(([k, x]) => ({ json: {
  config: x.config,
  group: k.replace(x.config + ' | ', ''),
  queries: x.n,
  hit_at_3: +(x.hit / x.n).toFixed(2),
  mrr: +(x.rr / x.n).toFixed(2),
  avg_chars: Math.round(x.chars / x.n)
}}));

